function src(id,tags=['marvel']){return{id,def:{tags}}}
function strongest(range=900){const p=game?.player;if(!p)return null;const a=(game.enemies||[]).filter(e=>e&&!e.dead&&!e.isCaptive&&Math.hypot(e.x-p.x,e.y-p.y)<=range);a.sort((x,y)=>(Number(y.isBoss)-Number(x.isBoss))||(Number(y.isMiniBoss)-Number(x.isMiniBoss))||(Number(y.elite)-Number(x.elite))||((y.maxHp||0)-(x.maxHp||0)));return a[0]||null}
function targets(x,y,range=450,n=5){return (game.enemies||[]).filter(e=>e&&!e.dead&&!e.isCaptive&&Math.hypot(e.x-x,e.y-y)<=range).sort((a,b)=>(Number(b.isBoss)-Number(a.isBoss))||(b.maxHp||0)-(a.maxHp||0)).slice(0,n)}
function line(x1,y1,x2,y2,w,color){game.beams.push({x1,y1,x2,y2,width:w,color,life:.12})}
function coreDefByChar(id){return CORES[CONTENT[id]?.core]||null}
function coreState(g=game,id=g?.characterId){if(!g||!SET.has(id))return null;if(!g.vsxMarvelCore||g.vsxMarvelCore.characterId!==id)g.vsxMarvelCore={characterId:id,meter:0,surgeUntil:0,surgeHeld:false,lastX:g.player?.x||0,lastY:g.player?.y||0,lastHp:g.player?.hp||0,impact:0,lastShot:0,phase:'SHRINK',phaseProgress:0,actionCd:0,guardAngle:0,guardTargetAngle:0,guardPulse:0,guardCd:0,guardBlocks:0};return g.vsxMarvelCore}
function coreGain(id,n){const g=game,s=coreState(g,id);if(!s||id==='marvel_hulk'||id==='marvel_ant_man')return;if(s.surgeHeld&&g.time<(s.surgeUntil||0)){s.meter=100;return;}s.meter=clampN((s.meter||0)+n,0,100);if(s.meter>=100&&g.time>=(s.surgeUntil||0)){s.meter=100;s.surgeHeld=true;s.surgeUntil=g.time+({marvel_iron_man:4,marvel_thor:4.5,marvel_captain_america:5,marvel_scarlet_witch:5,marvel_black_widow:5,marvel_hawkeye:4.5,marvel_falcon:4.5,marvel_winter_soldier:4}[id]||4);const c=coreDefByChar(id);game.texts.push(new FloatingText(g.player.x,g.player.y-46,c?.tag?.[VSX.lang]||'CORE SURGE',c?.color||'#8eefff',12));if(id==='marvel_captain_america')g.player.overhealShield=Math.min(g.player.maxHp*.35,(g.player.overhealShield||0)+g.player.maxHp*.18);if(id==='marvel_scarlet_witch'){for(const e of targets(g.player.x,g.player.y,360,10)){e.vsxMarvelHexUntil=g.time+3;g.damageEnemy(e,24*g.player.damageMultiplier,{source:src('marvel_chaos_core',['arcane','area']),canCrit:true,damageType:'arcane'})}g.effects.push(new WaveEffect(g.player.x,g.player.y,260,.45,28*g.player.damageMultiplier,40,src('marvel_chaos_core'), '#ff5f83'))}}
}
function coreSurge(id){const s=coreState(game,id);return !!s&&game.time<(s.surgeUntil||0)}

