function applyAntForm(g,phase,force=false){if(g.characterId!=='marvel_ant_man'||!g.player)return;const st=coreState(g,'marvel_ant_man');if(!force&&st.appliedPhase===phase)return;st.appliedPhase=phase;const p=g.player,ratio=p.hp/Math.max(1,p.maxHp);if(phase==='GIANT'){Object.assign(CHARACTER_DEFINITIONS.marvel_ant_man.mods,MARVEL_BASE_FORMS.antGiant);p.radius=24}else{Object.assign(CHARACTER_DEFINITIONS.marvel_ant_man.mods,MARVEL_BASE_FORMS.antShrink);p.radius=9}p.recalc?.();p.hp=clampN(p.maxHp*ratio,1,p.maxHp);g.spark?.(p.x,p.y,phase==='GIANT'?'#ef7377':'#dce9ef',14)}
function applyHulkUltForm(g,on){if(g.characterId!=='marvel_hulk'||!g.player)return;const p=g.player;if(on){Object.assign(CHARACTER_DEFINITIONS.marvel_hulk.mods,{hp:4.0,armor:14,incoming:.38});p.radius=22}else{Object.assign(CHARACTER_DEFINITIONS.marvel_hulk.mods,MARVEL_BASE_FORMS.hulk);p.radius=15}p.recalc?.();if(on)p.hp=p.maxHp;else p.hp=Math.min(p.maxHp,p.hp)}
