function ensureHouseParty(g,u){if(!u||u.id!=='marvel_house_party'||u.time<=0)return[];u.armors ||= [];for(let i=0;i<HOUSE_PARTY_ARMOR_SPECS.length;i++){let a=u.armors[i];if(!a||a.dead||!g.turrets.includes(a)){a=new VSX_HousePartyArmor(g,u,HOUSE_PARTY_ARMOR_SPECS[i],i);u.armors[i]=a;g.turrets.push(a)}}return u.armors}
